'use strict';
const test = require('node:test');
const assert = require('node:assert/strict');
const { performance } = require('node:perf_hooks');
const { diffLines, unifiedHunks, applyHunks } = require('./src/diff');
const { splitLines, joinLines } = require('./src/lines');

function lcs(a, b) {
  const row = Array(b.length + 1).fill(0);
  for (const line of a) {
    let diagonal = 0;
    for (let j = 1; j <= b.length; j++) {
      const previous = row[j];
      row[j] = line === b[j - 1] ? diagonal + 1 : Math.max(row[j], row[j - 1]);
      diagonal = previous;
    }
  }
  return row[b.length];
}

test('exhaustive minimality, ordering, deterministic repeated lines, and roundtrips', () => {
  const arrays = [[]];
  let level = [[]];
  for (let length = 1; length <= 4; length++) {
    level = level.flatMap(a => ['', '-line', '+line'].map(line => [...a, line]));
    arrays.push(...level);
  }
  for (const inputA of arrays) {
    for (const inputB of arrays) {
      const a = Object.freeze([...inputA]);
      const b = Object.freeze([...inputB]);
      const script = diffLines(a, b);
      assert.deepEqual(script.filter(e => e.op !== 'insert').map(e => e.line), a);
      assert.deepEqual(script.filter(e => e.op !== 'delete').map(e => e.line), b);
      assert.equal(script.filter(e => e.op !== 'equal').length, a.length + b.length - 2 * lcs(a, b));
      assert.deepEqual(diffLines(a, b), script);
      let inserted = false;
      for (const entry of script) {
        assert.ok(['equal', 'delete', 'insert'].includes(entry.op));
        if (entry.op === 'equal') inserted = false;
        else if (entry.op === 'insert') inserted = true;
        else assert.equal(inserted, false);
      }
      for (const context of [0, 1, 2, 3]) {
        const hunks = unifiedHunks(a, b, { context });
        for (const hunk of hunks) {
          Object.freeze(hunk.lines);
          Object.freeze(hunk);
        }
        Object.freeze(hunks);
        assert.deepEqual(applyHunks(a, hunks), b);
      }
    }
  }
});

test('zero ranges at top, middle, and EOF use preceding line coordinates', () => {
  const cases = [
    [[], ['x'], { oldStart: 0, oldLines: 0, newStart: 1, newLines: 1, lines: ['+x'] }],
    [['x'], [], { oldStart: 1, oldLines: 1, newStart: 0, newLines: 0, lines: ['-x'] }],
    [['a', 'b'], ['x', 'a', 'b'], { oldStart: 0, oldLines: 0, newStart: 1, newLines: 1, lines: ['+x'] }],
    [['a', 'b'], ['a', 'x', 'b'], { oldStart: 1, oldLines: 0, newStart: 2, newLines: 1, lines: ['+x'] }],
    [['a', 'b'], ['a', 'b', 'x'], { oldStart: 2, oldLines: 0, newStart: 3, newLines: 1, lines: ['+x'] }],
    [['x', 'a', 'b'], ['a', 'b'], { oldStart: 1, oldLines: 1, newStart: 0, newLines: 0, lines: ['-x'] }],
    [['a', 'x', 'b'], ['a', 'b'], { oldStart: 2, oldLines: 1, newStart: 1, newLines: 0, lines: ['-x'] }],
    [['a', 'b', 'x'], ['a', 'b'], { oldStart: 3, oldLines: 1, newStart: 2, newLines: 0, lines: ['-x'] }],
  ];
  for (const [a, b, hunk] of cases) {
    assert.deepEqual(unifiedHunks(a, b, { context: 0 }), [hunk]);
    assert.deepEqual(applyHunks(a, [hunk]), b);
  }
});

test('context merge boundary and complete-file coordinates after offsets', () => {
  assert.deepEqual(unifiedHunks(['a', 'b', 'c', 'd'], ['A', 'b', 'c', 'D'], { context: 1 }), [
    { oldStart: 1, oldLines: 4, newStart: 1, newLines: 4, lines: ['-a', '+A', ' b', ' c', '-d', '+D'] },
  ]);
  assert.deepEqual(unifiedHunks(['a', 'b', 'c', 'd', 'e'], ['A', 'b', 'c', 'd', 'E'], { context: 1 }), [
    { oldStart: 1, oldLines: 2, newStart: 1, newLines: 2, lines: ['-a', '+A', ' b'] },
    { oldStart: 4, oldLines: 2, newStart: 4, newLines: 2, lines: [' d', '-e', '+E'] },
  ]);
  const a = ['a', 'b', 'c', 'd', 'e'];
  const b = ['x', 'a', 'b', 'd', 'e', 'y'];
  const expected = [
    { oldStart: 0, oldLines: 0, newStart: 1, newLines: 1, lines: ['+x'] },
    { oldStart: 3, oldLines: 1, newStart: 3, newLines: 0, lines: ['-c'] },
    { oldStart: 5, oldLines: 0, newStart: 6, newLines: 1, lines: ['+y'] },
  ];
  assert.deepEqual(unifiedHunks(a, b, { context: 0 }), expected);
  assert.deepEqual(applyHunks(a, expected), b);
  assert.deepEqual(unifiedHunks(a, a), []);
  const copy = applyHunks(a, []);
  assert.deepEqual(copy, a);
  assert.notEqual(copy, a);
});

test('malformed counts, coordinates, lines, mismatches, overlap, and ordering reject indexed hunk', () => {
  const a = ['a', 'b', 'c'];
  const valid = { oldStart: 2, oldLines: 1, newStart: 2, newLines: 1, lines: ['-b', '+B'] };
  const malformed = [null, {}, { ...valid, oldStart: 0 }, { ...valid, newStart: 0 },
    { ...valid, oldStart: 5 }, { ...valid, oldStart: -1 }, { ...valid, oldLines: 0 },
    { ...valid, newLines: 2 }, { ...valid, newStart: 3 }, { ...valid, oldLines: 1.5 },
    { ...valid, oldStart: NaN }, { ...valid, newLines: Infinity },
    { ...valid, lines: null }, { ...valid, lines: ['?b'] }, { ...valid, lines: [''] },
    { ...valid, lines: [null] }, { ...valid, lines: ['-wrong', '+B'] },
    { ...valid, lines: [' wrong'] }, { ...valid, lines: ['-b', '-c', '+B'] },
    { ...valid, oldLines: 3, lines: ['-b', '-c', '-d', '+B'] },
  ];
  for (const hunk of malformed) assert.throws(() => applyHunks(a, [hunk]), /hunk 0 does not apply/);
  assert.throws(() => applyHunks(a, [valid, valid]), /hunk 1 does not apply/);
  assert.throws(() => applyHunks(a, [valid, { oldStart: 1, oldLines: 1, newStart: 1, newLines: 1, lines: [' a'] }]), /hunk 1 does not apply/);
  assert.throws(() => applyHunks(a, [valid, { oldStart: 3, oldLines: 1, newStart: 2, newLines: 1, lines: [' c'] }]), /hunk 1 does not apply/);
});

test('line prefixes, LF and empty lines survive text roundtrip', () => {
  const a = splitLines('\n-leading\n+leading\n leading\nlast\n');
  const b = splitLines('\n+leading\n-new\n leading\nlast\n\n');
  assert.equal(joinLines(applyHunks(a, unifiedHunks(a, b))), joinLines(b));
});

test('20,000-line unique and repetitive inputs with small changes finish under one second', () => {
  for (const repeated of [false, true]) {
    const a = Array.from({ length: 20000 }, (_, i) => repeated ? 'same' : `line ${i}`);
    const b = [...a];
    b.splice(17000, 1);
    b.splice(10000, 1, 'replacement');
    b.splice(100, 0, 'inserted');
    const start = performance.now();
    const script = diffLines(a, b);
    const hunks = unifiedHunks(a, b);
    const result = applyHunks(a, hunks);
    const elapsed = performance.now() - start;
    assert.deepEqual(result, b);
    assert.equal(script.filter(e => e.op !== 'equal').length, 4);
    assert.ok(elapsed < 1000, `${elapsed.toFixed(2)} ms`);
    console.log(`${repeated ? 'repetitive' : 'unique'} 20,000-line diff + hunks + apply: ${elapsed.toFixed(2)} ms`);
  }
  const a = Array(20000).fill('');
  assert.deepEqual(applyHunks(a, unifiedHunks(a, [])), []);
  assert.deepEqual(applyHunks([], unifiedHunks([], a)), a);
});

